const RULES=[["Articles & déterminants", "A1–B1", "Articles définis, indéfinis et partitifs", "Le / la / les renvoient à un référent identifié ; un / une / des introduisent un élément ; du / de la / de l’ désignent une quantité non comptable.", "Je bois de l’eau. J’ai acheté une pomme. Je n’ai pas de pain.", "Après la négation courante, « du / de la / des » devient « de / d’ » ; attention aux exceptions avec être.", "N’écris pas « je n’ai pas du pain » dans l’usage neutre ; préfère « je n’ai pas de pain ».", "A1"], ["Accords & adjectifs", "A1–B2", "Accord de l’adjectif", "L’adjectif qualificatif s’accorde généralement en genre et en nombre avec le nom : grand → grande → grands → grandes. Certains adjectifs de couleur composés restent invariables.", "Une maison blanche ; des chemises bleu clair ; des robes vertes.", "Vérifie le nom auquel l’adjectif se rapporte et les exceptions (marron, orange, bleu clair).", "N’accorde pas automatiquement tous les noms de couleurs.", "A1"], ["Possessifs & démonstratifs", "A1–B1", "Ce / cet / cette / ces et mon / ma / mes", "Ce devant masculin, cet devant masculin commençant par voyelle ou h muet, cette devant féminin, ces au pluriel. Devant un féminin singulier commençant par voyelle, « mon / ton / son » évitent le hiatus.", "Cet étudiant ; cette étudiante ; mon amie ; ces livres.", "Repère genre et nombre, mais aussi la première lettre ou le son du nom.", "Ne dis pas « ma amie ».", "A1"], ["Présent & verbes", "A1–B1", "Présent de l’indicatif", "Accorde la terminaison avec le sujet et distingue les groupes verbaux et les irréguliers : nous faisons, vous dites, ils viennent.", "Je prends ; nous finissons ; vous faites ; ils vont.", "Identifie toujours le sujet, surtout s’il est éloigné du verbe.", "Ne généralise pas les terminaisons en -er aux autres groupes.", "A1"], ["Questions & négation", "A1–B1", "Interrogation et négation", "La négation simple encadre le verbe conjugué (« ne ... pas »). Une question peut employer l’intonation, « est-ce que » ou l’inversion.", "Il ne vient pas. Est-ce qu’elle arrive ? Où va-t-il ?", "À l’écrit formel, conserve « ne » et respecte le trait d’union à l’inversion.", "Ne confonds pas « ne ... plus » et « ne ... jamais ».", "A1"], ["Prépositions", "A1–C1", "Prépositions après les verbes", "La construction dépend du verbe : répondre à, parler de, dépendre de, participer à, penser à, se souvenir de.", "Elle répond à Paul. Elle parle de Paul. Elle se souvient de lui.", "Apprends le verbe avec sa préposition, pas isolément.", "Ne transforme pas « pallier une difficulté » en « pallier à une difficulté ».", "B1"], ["Passé composé", "A2–B2", "Passé composé et auxiliaires", "Le passé composé = auxiliaire avoir ou être au présent + participe passé. Certains verbes de déplacement et les pronominaux se construisent avec être.", "Elle est arrivée. Il a travaillé. Elles se sont levées.", "Avec être, accord avec le sujet en général, sous réserve des règles propres aux pronominaux.", "Ne mets pas systématiquement être devant tous les verbes de déplacement (j’ai marché).", "A2"], ["Imparfait & habitudes", "A2–B1", "Imparfait ou passé composé", "L’imparfait décrit une habitude, un état ou un arrière-plan ; le passé composé présente un événement délimité ou achevé.", "Il pleuvait quand le train est arrivé. Tous les jours, elle lisait.", "Cherche si l’action sert de décor ou si elle fait avancer le récit.", "Ne choisis pas le temps uniquement d’après « hier » ou « autrefois ».", "A2"], ["Plus-que-parfait", "B1–C1", "Antériorité : plus-que-parfait", "Auxiliaire à l’imparfait + participe passé. Utilisé pour une action achevée avant un repère passé.", "Quand nous sommes arrivés, le film avait commencé.", "Repère deux moments passés et lequel est antérieur.", "Ne remplace pas mécaniquement le plus-que-parfait par un passé composé.", "B1"], ["Futur & condition", "B1–B2", "Futur simple et conditionnel présent", "Le futur exprime un avenir présenté comme réalisable ; le conditionnel exprime une hypothèse, une demande polie ou un fait vu depuis le passé.", "Demain, je viendrai. Je viendrais si je pouvais.", "Distingue « -rai » du futur et « -rais » du conditionnel à la 1re personne.", "N’utilise pas le conditionnel après un « si » hypothétique classique : si je pouvais, je viendrais.", "B1"], ["Conditionnel passé", "B2–C1", "Hypothèse irréelle dans le passé", "Si + plus-que-parfait → conditionnel passé dans la principale. Auxiliaire au conditionnel présent + participe passé.", "Si elle avait étudié, elle aurait réussi. S’il était parti, il serait arrivé.", "Vérifie la chronologie et l’auxiliaire du verbe.", "Ne dis pas « si elle aurait su ».", "B2"], ["Subjonctif présent", "B1–C1", "Quand employer le subjonctif", "Après la nécessité, le doute, le souhait, la concession ou un but : il faut que, je doute que, bien que, pour que, afin que, avant que.", "Il faut que tu viennes. Bien qu’il soit tard, elle travaille.", "Repère l’expression déclencheuse puis conjugue au subjonctif.", "« Après que » est traditionnellement suivi de l’indicatif en français soigné.", "B2"], ["Subjonctif & nuance", "B2–C2", "Indicatif ou subjonctif selon le sens", "Certains verbes changent de construction selon l’affirmation ou la négation : je pense qu’il vient / je ne pense pas qu’il vienne (subjonctif fréquent).", "Il est certain qu’il vient ; il est possible qu’il vienne.", "Différencie certitude, doute et appréciation subjective.", "Ne mets pas le subjonctif après toutes les occurrences de « que ».", "C1"], ["Pronoms COD / COI", "B1–B2", "Le / la / les ou lui / leur", "Un COD se construit sans préposition : voir quelqu’un → le/la/les. Un COI introduit par « à » pour une personne : parler à Paul → lui parler.", "Je vois Marie : je la vois. Je parle à Marie : je lui parle.", "Pose les questions « qui ? quoi ? » puis « à qui ? ».", "Ne confonds pas « leur » pronom (invariable) et « leurs » déterminant possessif.", "B1"], ["Pronoms y et en", "B1–B2", "Y et en : complément de lieu, de chose, quantité", "Y remplace souvent un lieu ou « à + chose » ; en remplace « de + chose » ou une quantité. Attention aux verbes et aux personnes.", "Je vais à Paris → j’y vais. J’ai besoin de repos → j’en ai besoin.", "Teste la préposition originale du complément.", "N’utilise pas y/en systématiquement à la place d’un pronom personnel humain.", "B1"], ["Relatifs simples & connecteurs", "B1–B2", "Qui / que / dont / où", "Qui est généralement sujet, que est COD, dont remplace un complément en « de », où un lieu ou un moment.", "Le livre que j’ai lu ; la personne qui parle ; le sujet dont je parle ; le jour où il est venu.", "Reconstitue les deux phrases de départ pour trouver la fonction.", "Ne mets pas « que » lorsqu’il manque « de » (le sujet dont je parle).", "B1"], ["Relatifs composés", "B2–C1", "Lequel, auquel, duquel et leurs accords", "Après une préposition : lequel/laquelle/lesquels/lesquelles ; « à + lequel » → auquel ; « de + lequel » → duquel. Accords selon l’antécédent.", "Le projet auquel je participe. Les questions auxquelles je réponds. Le parc près duquel je vis.", "Repère l’antécédent, le genre, le nombre, puis la préposition exigée.", "« dont » ne remplace pas toujours « duquel » après « près de / à côté de ».", "B2"], ["Accord du participe passé", "B2–C2", "Avoir, être et COD antéposé", "Avec être : accord avec le sujet (cas général). Avec avoir : accord avec le COD seulement s’il est placé avant. Les pronominaux exigent une analyse de la fonction de « se ».", "Les lettres que j’ai écrites. Elle est partie. Elles se sont parlé (COI).", "Localise le COD avant le participe puis fais l’accord en genre et nombre. « fait » suivi d’un infinitif reste invariable.", "Ne fais pas l’accord avec le sujet pour un participe avec avoir sans COD antéposé.", "B2"], ["Homophones & orthographe", "B1–C2", "A/à, et/est, son/sont, ce/se, quoique/quoi que", "Les homophones ont la même prononciation, pas la même fonction. Utilise des tests de substitution : avait → a ; était → est ; cela → ce (selon contexte).", "Il a un livre à lire. Ils sont là. Il se prépare. Quoi que tu fasses...", "Teste la nature grammaticale (verbe, préposition, déterminant, pronom) avant de choisir.", "Ne confonds pas « quoique » (= bien que) et « quoi que » (= quelle que soit la chose que).", "B1"], ["Homophones & lexique", "B2–C2", "Quelque / quel que / quoi que / quoique", "« Quel que » s’accorde avec le nom : quelles que soient les raisons ; « quelque » + adjectif + que est adverbial et invariable ; « quoi que » = quelle que soit la chose que.", "Quelles que soient les difficultés. Quelque difficiles qu’elles soient. Quoi que tu dises.", "Cherche le verbe être et le nom, puis vérifie si les mots s’écrivent ensemble.", "Ne confonds pas « quelque » et « quelques » devant un nom pluriel.", "B2"], ["Discours rapporté", "B2–C1", "Concordance des temps", "Après un introducteur au passé, un présent peut devenir imparfait, un futur devient conditionnel et un passé composé peut devenir plus-que-parfait.", "« Je viendrai » → elle a dit qu’elle viendrait. « J’ai fini » → il a dit qu’il avait fini.", "Vérifie le temps introducteur et les marqueurs de temps/lieu.", "Ne recopie pas automatiquement le futur lorsque l’introducteur est au passé.", "B2"], ["Connecteurs & registre", "B1–C1", "Cause, conséquence, opposition, concession, but", "Parce que / puisque : cause ; donc / ainsi : conséquence ; pourtant / néanmoins : opposition ; bien que : concession ; pour que : but.", "Il pleut, pourtant elle sort. Il pleut, donc elle reste.", "Demande-toi quelle relation logique unit les propositions.", "Ne remplace pas « pourtant » par « par conséquent » : sens inverse.", "B1"], ["Concession & opposition", "B2–C2", "Bien que, quoique, malgré, toutefois", "Bien que / quoique demandent le subjonctif ; malgré est une préposition devant un nom ou un groupe nominal ; toutefois marque une opposition.", "Malgré la pluie, il sort. Bien qu’il pleuve, il sort.", "Observe la nature de ce qui suit : nom ou proposition avec verbe.", "Évite « malgré que » en français soigné ; préfère « bien que ».", "B2"], ["Concession complexe", "C1–C2", "À supposer que, pour peu que, encore que", "Ces locutions articulent hypothèse minimale, réserve ou concession et demandent souvent le subjonctif.", "À supposer qu’il accepte, que ferons-nous ? Pour peu qu’elle lise, elle comprendra.", "Mémorise chaque locution avec son mode et sa nuance.", "Ne traite pas toutes les concessions comme une simple opposition.", "C1"], ["Articulation argumentative", "C1–C2", "Nuancer et structurer un raisonnement", "En effet appuie une justification ; en revanche oppose ; dès lors conclut ; pour autant limite une inférence ; dans la mesure où justifie sous condition.", "Le projet avance ; pour autant, sa réussite n’est pas assurée.", "Cherche le rôle logique, pas seulement une traduction mot à mot.", "Ne confonds pas l’opposition avec la conséquence.", "C1"], ["Constructions verbales", "B2–C2", "Régimes verbaux et prépositions", "Une préposition dépend du verbe : parvenir à, s’abstenir de, se souvenir de, obvier à, pallier quelque chose.", "Ils parviennent à un accord ; il s’abstient de voter ; on pallie un manque.", "Apprends les couples verbe + préposition et teste avec un infinitif.", "Attention au piège « pallier à », déconseillé en français soigné.", "B2"], ["Inversion & style soutenu", "C1–C2", "Inversion et formes figées", "À l’écrit soutenu : encore faut-il que + subjonctif ; fût-ce = ne serait-ce que ; eût-il = même s’il avait (littéraire).", "Encore faut-il qu’il accepte. Fût-ce un détail, il importe.", "Apprends les locutions comme unités, avec leur registre.", "N’utilise pas ces tournures littéraires dans un email simple sans raison.", "C1"], ["Syntaxe littéraire", "C2", "Imparfait et plus-que-parfait du subjonctif", "Les formes « fût », « eût », « eût-il » appartiennent au registre littéraire ; leur reconnaissance est utile en compréhension avancée.", "Il fallait qu’il fût prêt. Eût-il su, il aurait agi autrement.", "Reconnais la fonction avant de chercher à employer ces formes dans la vie quotidienne.", "Ne confonds pas « fût » subjonctif avec « fut » passé simple.", "C2"], ["Lexique avancé", "C1–C2", "Nuances lexicales et collocations", "Un mot avancé doit convenir au sens et à sa construction : corroborer une hypothèse, obvier à une difficulté, s’enquérir de la situation.", "Les preuves corroborent la thèse. Il faut obvier à cet obstacle.", "Vérifie le registre et les prépositions du mot.", "Évite les synonymes approximatifs si leur construction diffère.", "C2"], ["Précision lexicale", "C1–C2", "Verbes d’analyse et de recommandation", "Préconiser = recommander ; corroborer = confirmer par des éléments de preuve ; étayer = appuyer par des arguments.", "Le rapport préconise une réforme. Les données corroborent cette hypothèse.", "La précision de sens l’emporte sur la complexité du vocabulaire.", "Ne choisis pas un mot uniquement parce qu’il semble plus soutenu.", "C1"], ["Pragmatique & cohérence", "C2", "Implicite et cohérence de discours", "L’interprétation dépend du contexte, de l’ironie, de la modalisation et de la portée des connecteurs ; « nonobstant » = malgré ; « sans préjudice de » = sans exclure.", "Nonobstant les critiques, il maintient sa décision.", "Détermine ce que le locuteur affirme, concède et laisse entendre.", "Ne considère pas tout énoncé comme littéral.", "C2"], ["Locutions & expressions", "C1–C2", "Locutions figées et registre", "À l’aune de = au regard de / en mesurant par rapport à ; à plus forte raison renforce une conclusion ; au demeurant = du reste.", "On jugera ce bilan à l’aune de ses résultats.", "Apprends le sens exact et la place de chaque locution dans la phrase.", "Ne substitue pas des locutions voisines sans vérifier la relation logique.", "C2"], ["Comparaison & quantité", "A2–B1", "Plus, moins, autant, aussi, meilleur", "Aussi + adjectif/adverbe, autant + nom/verbe, meilleur = comparatif de bon, mieux = comparatif de bien.", "Elle travaille aussi vite que moi ; il a autant de livres ; c’est mieux.", "Identifie la classe grammaticale de l’élément comparé.", "Ne confonds pas « meilleur » et « mieux ».", "A2"], ["Conditionnel présent", "A1–C2", "Réviser : Conditionnel présent", "Pour ce thème, repère la fonction des mots, l’accord, la préposition et le temps.", "Relis la proposition complète avant et après le blanc.", "Commence par éliminer les propositions incompatibles avec la construction.", "Ne choisis pas uniquement à l’oreille.", "B1"], ["Relatifs & prépositions", "A1–C2", "Réviser : Relatifs & prépositions", "Pour ce thème, repère la fonction des mots, l’accord, la préposition et le temps.", "Relis la proposition complète avant et après le blanc.", "Commence par éliminer les propositions incompatibles avec la construction.", "Ne choisis pas uniquement à l’oreille.", "B1"], ["Subtilités des modes", "A1–C2", "Réviser : Subtilités des modes", "Pour ce thème, repère la fonction des mots, l’accord, la préposition et le temps.", "Relis la proposition complète avant et après le blanc.", "Commence par éliminer les propositions incompatibles avec la construction.", "Ne choisis pas uniquement à l’oreille.", "B1"]];
const COURSES={"Articles & déterminants":{"objectif":"Les articles placés devant les noms indiquent si l'on parle d'un élément connu, d'un élément non identifié ou d'une quantité. Ils aident à construire une phrase précise et naturelle.","quand":["Quand le lecteur sait déjà de quel élément on parle : le, la, l', les.","Quand on introduit un élément parmi d'autres : un, une, des.","Quand on parle d'une quantité non dénombrée : du, de la, de l'."],"regles":[{"titre":"Articles définis","explication":"Le / la / l’ / les désignent un élément identifié, générique ou unique dans le contexte. L’élision l’ précède une voyelle ou un h muet.","exemple":"Ferme la porte. J'aime le cinéma. L'école ouvre demain."},{"titre":"Articles indéfinis","explication":"Un / une / des présentent une personne ou une chose non identifiée : « une idée » n'est pas « l'idée ».","exemple":"J'ai rencontré une étudiante. Des voisins arrivent."},{"titre":"Partitifs","explication":"Du / de la / de l' servent pour une quantité non précisée ou une matière. Avec un nom dénombrable, on peut dire « un » pour une unité.","exemple":"Je veux du pain, de la confiture, de l'eau."},{"titre":"Négation et quantités","explication":"Avec ne…pas et une quantité indéfinie, un/une/des/du/de la deviennent généralement de/d' ; avec être, l'article reste possible.","exemple":"Je n'ai pas de café. Ce n'est pas une erreur."},{"titre":"Adjectif avant un pluriel","explication":"Dans l'usage soigné, des devient souvent de devant un adjectif antéposé, sauf dans certains groupes figés.","exemple":"De belles photos ; des jeunes gens (groupe lexical)."}],"nuances":["Après aimer, détester, préférer, on emploie souvent l'article défini pour une généralité : « J'aime le thé ».","Avec beaucoup, trop, peu, assez + nom : « beaucoup de temps », pas « beaucoup du temps » dans le sens neutre.","Des est parfois la contraction de de + les : « Je parle des élèves » ; ce n'est pas un indéfini."],"pieges":["❌ « Je n'ai pas du pain » → ✅ « Je n'ai pas de pain » (négation de quantité, sens neutre).","❌ « Je mange de le pain » → ✅ « Je mange du pain » (de + le = du).","❌ « beaucoup des livres » → ✅ « beaucoup de livres » dans la plupart des contextes."],"retenir":["Défini = connu/général ; indéfini = non identifié ; partitif = quantité non comptée.","À la négation de quantité : généralement de/d'.","Vérifier genre, nombre et présence d'une voyelle."],"methode":["1. Trouve le nom qui suit le blanc.","2. Demande-toi s'il est identifié, non identifié ou en quantité.","3. Cherche une négation ou une expression de quantité avant de choisir."]},"Accords & adjectifs":{"objectif":"L’adjectif apporte une information sur un nom : qualité, couleur, apparence ou appréciation. Il sert à décrire avec précision. Au TCF, l’enjeu est de trouver le mot qu’il qualifie, puis d’appliquer l’accord correct, y compris les exceptions.","quand":["Pour décrire une personne, une chose ou une situation : une décision importante.","Pour comparer ou nuancer : des résultats meilleurs, un objectif ambitieux.","Pour caractériser après un verbe d'état : ces propositions semblent pertinentes."],"regles":[{"titre":"Accord de base","explication":"L'adjectif qualificatif s'accorde en genre (masculin/féminin) et en nombre (singulier/pluriel) avec le nom ou le pronom qu'il qualifie, qu'il soit avant ou après.","exemple":"Un projet sérieux ; une idée sérieuse ; des projets sérieux ; des idées sérieuses."},{"titre":"Formation du féminin","explication":"On ajoute souvent -e ; certaines formes changent : -f → -ve, -eux → -euse, -er → -ère. La forme en -e reste souvent identique.","exemple":"Actif → active ; heureux → heureuse ; premier → première ; utile → utile."},{"titre":"Formation du pluriel","explication":"On ajoute souvent -s. Les adjectifs en -s/-x restent généralement inchangés au masculin pluriel ; beaucoup en -al deviennent -aux, mais il existe des exceptions.","exemple":"Un cours intéressant → des cours intéressants ; un enjeu national → des enjeux nationaux."},{"titre":"Adjectif attribut","explication":"Après être, sembler, devenir, rester, paraître, l'adjectif s'accorde avec le sujet, même quand il en est éloigné.","exemple":"Ces mesures semblent efficaces. La solution demeure complexe."},{"titre":"Couleurs simples et composées","explication":"Les adjectifs de couleur simples s'accordent généralement. Les couleurs exprimées par un nom (orange, marron) ou un composé (bleu clair, vert foncé) sont généralement invariables.","exemple":"Des robes vertes ; des sacs orange ; des yeux bleu clair."},{"titre":"Accord avec plusieurs noms","explication":"Un adjectif qualifiant des noms de genres différents est traditionnellement au masculin pluriel ; attention à identifier s'il se rapporte à un seul nom ou au groupe.","exemple":"Un bureau et une salle lumineux ; une table et des chaises neuves."},{"titre":"Place et sens de l'adjectif","explication":"Certaines positions changent le sens. « Ancien », « grand », « pauvre », « propre » n'ont pas toujours le même sens avant et après le nom.","exemple":"Mon ancien professeur ≠ un professeur ancien ; un grand homme ≠ un homme grand."}],"nuances":["Beau → bel devant un masculin singulier commençant par voyelle ou h muet : « un bel appartement », mais « une belle maison ».","Vieux → vieil devant voyelle/h muet ; nouveau → nouvel : « un vieil ami », « un nouvel emploi ».","« Des roses et des tulipes rouges » peut être ambigu : l'accord seul n'indique pas toujours exactement les éléments visés.","« Tout » adverbe est souvent invariable mais peut s'accorder devant un adjectif féminin commençant par une consonne ou un h aspiré : « elle est toute petite », « elle est tout heureuse » (h muet)."],"pieges":["❌ « des maisons blanc » → ✅ « des maisons blanches » : féminin pluriel.","❌ « des chemises bleues claires » → ✅ « des chemises bleu clair » : couleur composée invariable.","❌ « des pantalons oranges » → ✅ « des pantalons orange » : nom utilisé comme couleur.","❌ « une bel histoire » → ✅ « une belle histoire » : « bel » est masculin.","❌ « les décisions sont pertinent » → ✅ « les décisions sont pertinentes » : attribut du sujet."],"retenir":["Question réflexe : « Quel nom est décrit ? » → genre + nombre → forme de l'adjectif.","Adjectif simple : accord, sauf exceptions. Couleur composée : invariable.","Attention au sens quand l'adjectif change de place."],"methode":["1. Souligne le nom, même si l'adjectif est éloigné.","2. Repère genre et nombre ; vérifie si c'est une couleur simple, composée ou un nom de couleur.","3. Cherche les formes particulières : beau/bel, nouveau/nouvel, vieux/vieil.","4. Relis la phrase pour vérifier le sens (ancien/grand/pauvre, etc.)."]},"Possessifs & démonstratifs":{"objectif":"Les déterminants possessifs montrent à qui appartient ou se rattache un nom ; les démonstratifs désignent une personne ou une chose dans la situation ou le texte.","quand":["Pour parler de sa famille, de son matériel, de son avis : mon, ton, son, notre…","Pour montrer ou reprendre un élément précis : ce, cet, cette, ces.","Pour distinguer deux éléments : celui-ci, celle-là, ces personnes-ci."],"regles":[{"titre":"Possessif et nom possédé","explication":"Le possessif s'accorde avec le nom possédé, pas avec le sexe de la personne qui possède : sa voiture, son vélo. Le pluriel « leur/leurs » dépend du nombre d'objets possédés.","exemple":"Marie parle de son frère et de sa sœur. Ils prennent leurs sacs."},{"titre":"Mon/ton/son devant voyelle","explication":"Devant un nom féminin singulier commençant par une voyelle ou un h muet, on emploie mon, ton, son pour éviter le hiatus.","exemple":"Mon amie, ton école, son histoire."},{"titre":"Démonstratifs","explication":"Ce + masculin singulier, cet + masculin singulier devant voyelle/h muet, cette + féminin singulier, ces + pluriel.","exemple":"Ce livre ; cet arbre ; cette idée ; ces documents."},{"titre":"Pronoms démonstratifs","explication":"Celui, celle, ceux, celles remplacent le nom et demandent souvent une précision : de…, qui…, -ci/-là.","exemple":"Mon dossier est prêt ; celui de Paul ne l'est pas."}],"nuances":["« Cet » dépend du son initial, pas seulement de la lettre : cet homme (h muet), ce héros (h aspiré).","« Leur » déterminant devient « leurs » quand chaque possesseur possède plusieurs objets, selon le sens ; « leur » pronom COI est invariable."],"pieges":["❌ « ma amie » → ✅ « mon amie ».","❌ « cette arbre » → ✅ « cet arbre ».","❌ « Je leur ai écrit des lettres à leurs » → ✅ « Je leur ai écrit des lettres » : pronom COI invariable."],"retenir":["Déterminant = devant un nom ; pronom = remplace un nom.","Ce/cet/cette/ces dépendent du nom désigné. Son/sa/ses dépendent du nom possédé."],"methode":["1. Vérifie s'il faut un déterminant ou un pronom.","2. Trouve le genre et le nombre du nom.","3. Pour masculin singulier, écoute voyelle/h muet pour choisir ce/cet."]},"Présent & verbes":{"objectif":"Le présent de l’indicatif situe une action actuelle, une habitude ou une vérité générale. Il sert aussi parfois pour un futur proche dans le contexte.","quand":["Pour décrire maintenant : je travaille.","Pour une habitude : elle court le samedi.","Pour une vérité générale ou un horaire : l'eau bout à 100 °C ; le train part demain."],"regles":[{"titre":"Verbes en -er","explication":"Le modèle régulier est -e, -es, -e, -ons, -ez, -ent ; attention aux modifications orthographiques.","exemple":"Je parle, nous parlons, ils parlent ; nous mangeons."},{"titre":"Verbes en -ir type finir","explication":"Le modèle -is, -is, -it, -issons, -issez, -issent concerne les verbes du 2e groupe ; tous les -ir ne le suivent pas.","exemple":"Je finis, nous finissons ; mais je pars, nous partons."},{"titre":"Verbes fréquents irréguliers","explication":"Avoir, être, aller, faire, dire, venir, pouvoir et vouloir ont des formes à mémoriser.","exemple":"Vous faites ; vous dites ; ils viennent ; nous allons."},{"titre":"Accord avec le sujet","explication":"Le verbe s'accorde avec le sujet réel, même si un complément ou une relative sépare le sujet du verbe.","exemple":"Les documents du candidat sont prêts ; c'est moi qui suis responsable."}],"nuances":["Après « chacun », « personne », « tout le monde », le verbe est généralement au singulier.","Certaines graphies se ressemblent à l'oral : ils parlent / il parle ; à l'écrit, regarde le sujet."],"pieges":["❌ « vous faisez » → ✅ « vous faites ».","❌ « elles vient » → ✅ « elles viennent ».","❌ « les résultats de l'analyse est bon » → ✅ « les résultats … sont bons »."],"retenir":["Le sujet commande le verbe, pas le nom le plus proche.","Apprends les formes irrégulières comme des blocs : vous dites, nous faisons, ils viennent."],"methode":["1. Encadre le sujet du verbe.","2. Identifie infinitif et groupe de conjugaison.","3. Vérifie les verbes irréguliers avant de retenir une terminaison."]},"Questions & négation":{"objectif":"L’interrogation permet d’obtenir une information ; la négation sert à nier, limiter ou exclure quelque chose. Les marqueurs choisis changent le sens.","quand":["Demander : où, quand, pourquoi, combien, lequel.","Nier un fait : ne…pas.","Exprimer la cessation, l'absence ou la limitation : ne…plus, ne…jamais, ne…que."],"regles":[{"titre":"Question directe","explication":"À l'écrit soigné : est-ce que ou inversion du sujet pronominal ; l'intonation suffit dans un registre familier.","exemple":"Est-ce qu'il vient ? Viendra-t-il ? Il vient ?"},{"titre":"Inversion et -t-","explication":"Un -t- euphonique apparaît entre deux voyelles avec il/elle/on dans certaines inversions ; on met des traits d'union.","exemple":"A-t-il compris ? Où va-t-elle ?"},{"titre":"Négation simple","explication":"Ne…pas entoure le verbe conjugué ; dans un temps composé, pas précède le participe.","exemple":"Elle ne parle pas. Elle n'a pas répondu."},{"titre":"Négations spécialisées","explication":"Ne…jamais = à aucun moment ; ne…plus = cessation ; ne…personne = aucune personne ; ne…que = seulement (restriction).","exemple":"Il ne vient jamais. Il ne vient plus. Il ne voit personne. Il n'a que dix minutes."}],"nuances":["« Rien » sujet : « Rien ne change » ; « personne » sujet : « Personne ne sait ».","« Ne » explétif après « avant que » ou « à moins que » ne constitue pas une négation.","Dans le français oral familier, le « ne » est fréquemment omis ; au TCF écrit, privilégie la forme complète."],"pieges":["❌ « Je n'ai vu pas » → ✅ « Je n'ai pas vu ».","❌ Confondre « plus » (cessation) et « jamais » (fréquence nulle).","❌ Lire « ne…que » comme une négation totale : cela signifie « seulement »."],"retenir":["Question formelle : est-ce que / inversion.","Temps composé : ne + auxiliaire + pas + participe.","Ne…que = seulement."],"methode":["1. Identifie si la phrase demande, nie ou restreint.","2. Repère le verbe conjugué pour placer la négation.","3. Contrôle le sens précis : jamais, plus, aucun, que."]},"Prépositions":{"objectif":"Une préposition relie les groupes de mots : elle indique lieu, temps, cause, but ou complément d’un verbe. De nombreuses constructions sont fixées par l’usage.","quand":["Pour parler d'un lieu : à, en, au, aux, chez, dans, sur.","Pour exprimer le temps : depuis, pendant, en, dans.","Pour compléter un verbe : dépendre de, répondre à, compter sur."],"regles":[{"titre":"Verbes construits avec à","explication":"Apprends chaque verbe avec sa préposition : participer à, répondre à, faire confiance à, s'intéresser à.","exemple":"Il participe à une réunion. Elle s'intéresse aux langues."},{"titre":"Verbes construits avec de","explication":"Dépendre de, se souvenir de, avoir besoin de, se méfier de ; la préposition peut guider le choix de « dont » ou « en ».","exemple":"Le résultat dépend de toi ; le sujet dont nous parlons."},{"titre":"Verbes sans préposition","explication":"Certains verbes sont transitifs directs : attendre quelqu'un, aider quelqu'un, pallier une difficulté.","exemple":"J'attends le bus ; elle pallie une absence."},{"titre":"Pays et lieux","explication":"En avec beaucoup de pays féminins et certains masculins commençant par voyelle ; au devant pays masculins consonantiques ; aux au pluriel.","exemple":"En France, en Iran, au Maroc, aux États-Unis."},{"titre":"Temps : depuis / pendant / en / dans","explication":"Depuis = origine qui se prolonge ; pendant = durée ; en = temps nécessaire ; dans = délai futur.","exemple":"J'étudie depuis deux ans ; je termine en une heure ; je pars dans une heure."}],"nuances":["« Auprès de » indique proximité/contact, « près de » proximité spatiale ; « grâce à » est plutôt positif, « à cause de » plutôt négatif.","Un même verbe peut changer de sens selon la préposition : penser à un ami / penser de ce film."],"pieges":["❌ « pallier à un problème » → ✅ « pallier un problème ».","❌ « Je vais en Maroc » → ✅ « Je vais au Maroc ».","❌ « Je pars en deux heures » si l'on veut dire « après deux heures » → ✅ « dans deux heures »."],"retenir":["Mémorise verbe + préposition + exemple.","Pour les lieux, le genre du pays compte.","Depuis = point de départ ; pendant = durée ; dans = délai."],"methode":["1. Cherche si la préposition dépend du verbe.","2. Remplace mentalement le groupe par une construction connue.","3. Vérifie si le contexte exprime temps, lieu, but, cause ou opposition."]},"Passé composé":{"objectif":"Le passé composé situe un événement accompli, souvent important dans le récit. Il se forme avec un auxiliaire conjugué au présent et un participe passé.","quand":["Pour raconter une action achevée : j'ai terminé.","Pour parler d'un événement qui interrompt une description : il pleuvait quand il est arrivé.","Pour faire un bilan : nous avons progressé."],"regles":[{"titre":"Formation","explication":"Auxiliaire avoir ou être au présent + participe passé : -é, -i, -u ou formes irrégulières.","exemple":"Nous avons étudié ; elle est partie ; j'ai pris."},{"titre":"Auxiliaire avoir","explication":"C'est l'auxiliaire de la majorité des verbes. Le participe passé reste généralement invariable si le COD suit.","exemple":"Elle a lu trois livres ; ils ont préparé leur dossier."},{"titre":"Auxiliaire être","explication":"Plusieurs verbes intransitifs de déplacement/changement d'état et les pronominaux utilisent être. Accord avec le sujet en général (cas particuliers des pronominaux).","exemple":"Elle est arrivée ; elles sont sorties ; ils se sont levés."},{"titre":"Double emploi selon la construction","explication":"Certains verbes changent d'auxiliaire selon qu'ils sont employés intransitivement ou avec un COD.","exemple":"Elle est sortie. Elle a sorti les poubelles."}],"nuances":["Ne déduis pas automatiquement l'auxiliaire du sens de déplacement : « J'ai marché », « j'ai couru ».","L'accord avec avoir peut apparaître si le COD précède : « les lettres que j'ai écrites » ; c'est étudié au chapitre « Accord du participe passé »."],"pieges":["❌ « J'ai allé » → ✅ « Je suis allé(e) ».","❌ « J'ai marché » transformé en « je suis marché » : incorrect.","❌ « Elle est arrivé » → ✅ « Elle est arrivée »."],"retenir":["Formule = auxiliaire au présent + participe passé.","Avec être : vérifier l'accord ; avec avoir : chercher un éventuel COD placé avant."],"methode":["1. Identifie le verbe et son auxiliaire.","2. Forme correctement le participe passé.","3. Vérifie l'accord selon avoir/être et la structure de la phrase."]},"Imparfait & habitudes":{"objectif":"L’imparfait décrit des situations, habitudes ou actions en cours dans le passé ; le passé composé présente un événement terminé ou qui fait avancer le récit.","quand":["Pour planter le décor : il faisait froid.","Pour une répétition passée : chaque été, nous partions.","Pour distinguer action de fond et action ponctuelle : je dormais quand il a appelé."],"regles":[{"titre":"Formation de l'imparfait","explication":"Base de « nous » au présent sans -ons + ais, ais, ait, ions, iez, aient ; exception importante : être → ét-.","exemple":"Nous parlons → je parlais ; nous finissons → ils finissaient ; il était."},{"titre":"Valeur descriptive","explication":"L'imparfait exprime durée non bornée, état, habitude ou contexte.","exemple":"Quand j'étais petit, je lisais beaucoup."},{"titre":"Valeur événementielle du passé composé","explication":"Le passé composé sert pour une action perçue comme accomplie ou délimitée.","exemple":"Hier, j'ai lu un livre ; le téléphone a sonné."},{"titre":"Combinaison dans le récit","explication":"Le décor à l'imparfait peut être interrompu par un événement au passé composé.","exemple":"Je travaillais quand elle est entrée."}],"nuances":["« Hier » n'impose pas à lui seul le passé composé : « Hier, il pleuvait toute la journée » est possible.","« Pendant deux heures » peut accompagner le passé composé si la durée est considérée comme achevée."],"pieges":["❌ Choisir l'imparfait uniquement parce qu'une action est « longue ».","❌ « Quand j'ai été petit… » dans le sens habituel → ✅ « Quand j'étais petit… ».","❌ Confondre habitude (« je jouais ») et occurrence (« j'ai joué hier »)."],"retenir":["Imparfait = décor/état/habitude ; passé composé = événement/délimitation.","Le contexte entier décide, pas un seul adverbe."],"methode":["1. Imagine la scène : décor ou action principale ?","2. Cherche une habitude, un état ou une rupture.","3. Lis les deux propositions pour vérifier la chronologie."]},"Plus-que-parfait":{"objectif":"Le plus-que-parfait sert à situer une action antérieure à un autre moment passé. Il explique souvent la cause d’un résultat dans un récit.","quand":["Quand deux événements sont passés et que l'un a eu lieu avant l'autre.","Quand on évoque une expérience déjà achevée à un repère du passé.","Dans la condition irréelle du passé : si j'avais su…"],"regles":[{"titre":"Formation","explication":"Imparfait de avoir/être + participe passé ; les règles d'accord du participe s'appliquent.","exemple":"Elle avait terminé ; ils étaient arrivés."},{"titre":"Antériorité","explication":"L'action au plus-que-parfait se situe avant un repère passé exprimé ou sous-entendu.","exemple":"Quand je suis entré, la réunion avait commencé."},{"titre":"Condition hypothétique passée","explication":"Si + plus-que-parfait dans la subordonnée, conditionnel passé dans la principale.","exemple":"Si tu avais appelé, je serais venu."}],"nuances":["Le repère passé peut être à l'imparfait, au passé composé ou à un autre temps du récit.","Le plus-que-parfait n'est pas « le passé le plus ancien » en toute circonstance : il marque une antériorité relative."],"pieges":["❌ « Quand je suis arrivé, il a déjà parti » → ✅ « … il était déjà parti ».","❌ « Si j'aurais su » → ✅ « Si j'avais su ».","❌ Oublier l'auxiliaire à l'imparfait : « avait », pas « a »."],"retenir":["Plus-que-parfait = « déjà fait avant ce moment passé ».","Formule : avait / était + participe passé."],"methode":["1. Repère les deux points du temps passés.","2. Place l'action la plus ancienne au plus-que-parfait.","3. Vérifie auxiliaire et accord du participe passé."]},"Futur & condition":{"objectif":"Le futur annonce un événement présenté comme à venir ; le conditionnel exprime une hypothèse, une possibilité, une politesse ou un futur vu depuis le passé.","quand":["Pour une prévision ou une promesse : je partirai.","Pour une proposition polie : je voudrais.","Pour ce qui dépend d'une condition : je viendrais si je pouvais."],"regles":[{"titre":"Futur simple","explication":"Infinitif (ou radical irrégulier) + ai, as, a, ons, ez, ont ; « je viendrai » exprime le futur.","exemple":"Demain, je répondrai. Nous serons prêts."},{"titre":"Conditionnel présent","explication":"Radical du futur + terminaisons de l'imparfait : ais, ais, ait, ions, iez, aient.","exemple":"Je viendrais si j'avais le temps ; vous pourriez m'aider ?"},{"titre":"Si réel","explication":"Si + présent → futur / présent / impératif selon l'effet recherché.","exemple":"Si tu viens, nous partirons."},{"titre":"Si irréel présent","explication":"Si + imparfait → conditionnel présent.","exemple":"Si j'étais libre, je voyagerais davantage."}],"nuances":["En discours rapporté, « il a dit qu'il viendrait » exprime un futur dans le passé, pas nécessairement une condition.","À la première personne, -rai (futur) et -rais (conditionnel) sont un piège orthographique classique."],"pieges":["❌ « Si j'aurai le temps, je viendrai » → ✅ « Si j'ai le temps, je viendrai ».","❌ « Si je serais riche… » → ✅ « Si j'étais riche… ».","❌ « Demain je viendrais » sans hypothèse → ✅ « Demain je viendrai »."],"retenir":["Futur = -rai ; conditionnel = -rais (je).","Si + présent → futur ; si + imparfait → conditionnel."],"methode":["1. Cherche « si » et identifie la condition.","2. Décide si le fait est annoncé comme réel, hypothétique ou poli.","3. Vérifie les terminaisons -rai/-rais et les radicaux irréguliers."]},"Conditionnel passé":{"objectif":"Le conditionnel passé exprime un événement qui aurait pu se produire mais ne s’est pas produit, un regret, un reproche ou une information incertaine dans certains récits.","quand":["Pour imaginer une conséquence différente dans le passé.","Pour exprimer un regret ou un reproche : tu aurais dû prévenir.","Pour rapporter une information non confirmée : il aurait démissionné (emploi journalistique)."],"regles":[{"titre":"Formation","explication":"Auxiliaire avoir/être au conditionnel présent + participe passé ; accord selon l'auxiliaire et la fonction du COD.","exemple":"J'aurais accepté ; elle serait venue."},{"titre":"Irréel du passé","explication":"Si + plus-que-parfait dans la condition ; conditionnel passé pour la conséquence.","exemple":"Si nous avions réservé, nous aurions trouvé une place."},{"titre":"Regret et reproche","explication":"« Aurais dû / aurais pu / aurais voulu » expriment occasion manquée, reproche ou souhait irréalisé.","exemple":"Tu aurais dû vérifier la date ; j'aurais aimé participer."},{"titre":"Fait supposé","explication":"« Selon plusieurs sources, le ministre aurait annoncé… » indique une information non confirmée, et non une certitude.","exemple":"Le document aurait été modifié hier."}],"nuances":["Le conditionnel passé peut être utilisé sans « si » si la condition est implicite (« À ta place, j'aurais refusé »).","Ne confonds pas « il aurait annoncé » (information rapportée) et « il a annoncé » (fait affirmé)."],"pieges":["❌ « Si elle aurait travaillé, elle aurait réussi » → ✅ « Si elle avait travaillé… ».","❌ « Elle serait venu » → ✅ « Elle serait venue ».","❌ Employer le conditionnel passé pour un événement passé certain."],"retenir":["Si + plus-que-parfait → conditionnel passé.","Auxiliaire au conditionnel + participe passé."],"methode":["1. Vérifie si la situation est réelle ou contrefactuelle.","2. Repère condition et conséquence.","3. Applique les accords avec avoir/être."]},"Subjonctif présent":{"objectif":"Le subjonctif exprime une action envisagée à travers une nécessité, une volonté, un doute, un jugement ou un but. Il dépend souvent d'une expression principale.","quand":["Après la nécessité : il faut que, il est essentiel que.","Après la volonté : je souhaite que, je veux que.","Après le doute, la concession ou le but : je doute que, bien que, pour que."],"regles":[{"titre":"Formation régulière","explication":"Base de « ils » au présent, sans -ent + e, es, e, ions, iez, ent ; les verbes irréguliers sont fréquents.","exemple":"Que je parle, que nous parlions, qu'ils finissent."},{"titre":"Irréguliers indispensables","explication":"Être : sois/soit/soyons ; avoir : aie/ait/ayons ; aller : aille ; faire : fasse ; pouvoir : puisse ; savoir : sache.","exemple":"Il faut qu'elle soit présente ; pour que tu puisses venir."},{"titre":"Déclencheurs usuels","explication":"Il faut que, vouloir que, préférer que, douter que, pour que, afin que, avant que, bien que, quoique, jusqu'à ce que.","exemple":"Bien qu'il pleuve, nous sortirons."},{"titre":"But et sujets","explication":"Pour que introduit une subordonnée avec sujet propre ; avec même sujet, « pour + infinitif » est souvent préférable.","exemple":"Je travaille pour réussir ; je travaille pour que mes enfants réussissent."}],"nuances":["Après que est normalement suivi de l'indicatif dans la langue soignée : « après qu'il est parti » / « après qu'il sera parti » selon la chronologie.","« J'espère que » est généralement suivi de l'indicatif (« j'espère qu'il viendra »).","« Bien que » et « quoique » expriment la concession ; « quoi que » signifie « quelle que soit la chose que »."],"pieges":["❌ « Il faut que vous remplissez » → ✅ « … remplissiez ».","❌ « Bien qu'il a raison » → ✅ « … ait raison ».","❌ « J'espère qu'il vienne » → ✅ « … viendra » dans l'usage standard."],"retenir":["Déclencheur → subjonctif ; apprends l'expression avec le verbe.","Soit, ait, fasse, aille, puisse, sache sont essentiels au TCF."],"methode":["1. Repère la proposition introductrice avant « que ».","2. Détermine nécessité, souhait, doute, but ou concession.","3. Choisis la forme du subjonctif, surtout pour les verbes irréguliers."]},"Subjonctif & nuance":{"objectif":"À un niveau avancé, le choix entre indicatif et subjonctif dépend non seulement d'un mot déclencheur, mais aussi de la certitude, de la négation, de la temporalité et du point de vue du locuteur.","quand":["Quand on passe de « je pense » à « je ne pense pas ».","Quand un adjectif exprime un fait certain ou une possibilité.","Quand la proposition relative concerne un élément recherché plutôt qu'identifié."],"regles":[{"titre":"Opinion affirmative / négative","explication":"Je pense/crois que + indicatif si l'information est présentée comme vraie ; à la négation ou à l'interrogation, le subjonctif est fréquent si le fait est incertain.","exemple":"Je crois qu'il vient ; je ne crois pas qu'il vienne."},{"titre":"Certitude vs possibilité","explication":"Il est certain/évident que + indicatif ; il est possible / douteux que + subjonctif.","exemple":"Il est certain qu'elle a réussi ; il est possible qu'elle ait réussi."},{"titre":"Relative de recherche","explication":"Une relative peut prendre le subjonctif si l'antécédent est souhaité, hypothétique ou non identifié.","exemple":"Je cherche une personne qui sache parler japonais."},{"titre":"Subjonctif passé","explication":"Avoir/être au subjonctif présent + participe passé quand l'action est antérieure.","exemple":"Je regrette qu'elle soit partie ; je suis heureux qu'ils aient réussi."}],"nuances":["« Je ne doute pas que » se construit souvent avec l'indicatif si la certitude est affirmée ; le contexte nuance.","« Avant que » + subjonctif ; « après que » + indicatif dans la norme soignée.","Des formes du subjonctif imparfait/plus-que-parfait (qu'il fût, qu'il eût fait) relèvent surtout de textes littéraires."],"pieges":["❌ Appliquer le subjonctif à chaque « que ».","❌ « Il est évident qu'il soit là » en assertion neutre → ✅ « … qu'il est là ».","❌ « Je cherche un assistant qui sait… » peut signaler un assistant identifié ; si la personne est hypothétique : « qui sache… »."],"retenir":["Analyse d'abord le sens : certitude = indicatif ; éventualité/subjectivité = souvent subjonctif.","La négation peut changer le mode, mais pas mécaniquement dans tous les contextes."],"methode":["1. Localise le verbe d'opinion, de certitude ou d'évaluation.","2. Regarde la négation et si la personne/chose existe réellement.","3. Vérifie simultanéité et antériorité pour présent vs passé."]},"Pronoms COD / COI":{"objectif":"Les pronoms compléments évitent de répéter le même nom. Ils remplacent un complément direct (COD) ou indirect (COI) et doivent être placés correctement.","quand":["Pour reprendre une personne ou une chose déjà mentionnée.","Pour distinguer voir quelqu'un (COD) et parler à quelqu'un (COI).","Pour comprendre la place des pronoms dans les temps composés et avec infinitif."],"regles":[{"titre":"COD","explication":"Le, la, l', les remplacent un complément sans préposition. On demande « qui ? quoi ? » après le verbe.","exemple":"Je vois Marie → je la vois ; j'ai lu ces livres → je les ai lus."},{"titre":"COI humain","explication":"Lui / leur remplacent en général « à + personne » ; « leur » pronom ne prend jamais -s.","exemple":"Je téléphone à mes parents → je leur téléphone."},{"titre":"Placement","explication":"Devant le verbe conjugué ou devant l'infinitif auquel le complément appartient. Avec un temps composé, devant l'auxiliaire.","exemple":"Je vais le voir ; je l'ai vu ; je ne lui ai pas parlé."},{"titre":"Double pronoms","explication":"Ordre habituel : me/te/se/nous/vous + le/la/les + lui/leur + y + en (avec exceptions à l'impératif affirmatif).","exemple":"Je le lui donne ; elle m'en parle."}],"nuances":["Un complément de personne introduit par « de » se reprend souvent par de lui/d'elle et non automatiquement « en ».","L'impératif affirmatif change l'ordre : « Donne-le-moi », « Parlez-lui-en » (usage complexe)."],"pieges":["❌ « Je la téléphone » → ✅ « Je lui téléphone ».","❌ « Je leurs parle » → ✅ « Je leur parle ».","❌ « Je vais lui voir » → ✅ « Je vais le voir »."],"retenir":["COD = sans à → le/la/les. COI « à + personne » → lui/leur.","« Leur » pronom est invariable."],"methode":["1. Replace le complément dans la phrase complète.","2. Détermine s'il y a une préposition.","3. Choisis pronom et position ; pour avoir, surveille l'accord du participe passé."]},"Pronoms y et en":{"objectif":"Les pronoms y et en reprennent notamment un lieu, une chose introduite par une préposition ou une quantité. Ils évitent des répétitions lourdes.","quand":["Pour un lieu : j'y vais.","Pour « à + chose » : j'y pense.","Pour « de + chose », une quantité ou un partitif : j'en parle ; j'en veux deux."],"regles":[{"titre":"Y et lieu","explication":"« Y » remplace souvent un complément de lieu précédé de à, dans, chez, sur ou en.","exemple":"Tu vas au centre ? Oui, j'y vais."},{"titre":"Y et à + chose","explication":"« Y » reprend de nombreux compléments non humains introduits par à.","exemple":"Pense à ce projet → penses-y ; il y tient."},{"titre":"En et de + chose","explication":"« En » reprend « de + chose » et des expressions quantitatives.","exemple":"Il parle de ce problème → il en parle."},{"titre":"Quantité conservée","explication":"Quand en reprend un nom compté, le nombre ou la quantité reste exprimé après le verbe.","exemple":"J'ai trois cahiers → j'en ai trois ; j'en veux beaucoup."},{"titre":"Placement et impératif","explication":"Souvent avant le verbe ; à l'impératif affirmatif, généralement après avec trait d'union.","exemple":"J'y vais ; j'en parle ; vas-y ; parles-en."}],"nuances":["On préfère généralement « penser à lui / à elle » et non « y penser » quand il s'agit d'une personne, selon le verbe et le registre.","« En » peut aussi renvoyer à une origine : « Je reviens du bureau → j'en reviens »."],"pieges":["❌ « J'ai deux stylos, j'en ai » → ✅ « … j'en ai deux » si la quantité est l'information recherchée.","❌ « Je lui pense » → ✅ « Je pense à lui ».","❌ « Il en va à Paris » → ✅ « Il y va »."],"retenir":["Y ⇔ lieu ou à + chose. En ⇔ de + chose ou quantité.","Après « en », ne supprime pas le nombre nécessaire."],"methode":["1. Reconstitue le complément entier.","2. Identifie « à », « de » ou un lieu.","3. Vérifie si le référent est une personne et si un nombre doit rester."]},"Relatifs simples & connecteurs":{"objectif":"Les pronoms relatifs relient deux propositions et évitent de répéter un nom. Ils précisent de quelle personne, de quel lieu ou de quel événement il s'agit.","quand":["Pour ajouter une information sur un nom : la femme qui parle.","Pour reprendre un objet direct : le film que j'ai vu.","Pour éviter « de ce sujet » ou « à cet endroit » : dont, où."],"regles":[{"titre":"Qui sujet","explication":"« Qui » devient sujet du verbe de la relative ; le verbe s'accorde avec son antécédent.","exemple":"Les personnes qui travaillent ici sont compétentes."},{"titre":"Que COD","explication":"« Que/qu' » reprend le COD, sans préposition ; il peut influencer l'accord d'un participe passé avec avoir.","exemple":"Les photos que j'ai prises."},{"titre":"Dont","explication":"« Dont » remplace notamment « de + nom », si « de » est exigé par le verbe, le nom ou l'adjectif.","exemple":"Le sujet dont je parle ; une décision dont je suis fier."},{"titre":"Où","explication":"« Où » reprend un lieu ou un repère temporel ; on n'utilise pas « où » pour toutes les relations abstraites.","exemple":"La ville où je vis ; le jour où je suis parti."}],"nuances":["« Qui » ne signifie pas toujours « personne » : « le livre qui est sur la table ».","« Dont » ne s'ajoute pas à un autre de représentant le même complément : « le dossier dont je parle », sans « de »."],"pieges":["❌ « La personne que travaille » → ✅ « … qui travaille ».","❌ « Le livre dont j'ai lu » → ✅ « Le livre que j'ai lu ».","❌ « Le sujet que je parle » → ✅ « … dont je parle »."],"retenir":["QUI = sujet ; QUE = COD ; DONT = de ; OÙ = lieu/temps.","Reconstruis d'abord les deux phrases séparées."],"methode":["1. Observe le nom avant le blanc (antécédent).","2. Identifie la fonction manquante dans la relative.","3. Vérifie le verbe et sa préposition : parler de, participer à, etc."]},"Relatifs composés":{"objectif":"Les relatifs composés servent à reprendre un nom après une préposition. Leur forme dépend du genre et du nombre de l'antécédent.","quand":["Après avec, pour, sans, sur, dans, parmi : avec lequel, sur laquelle…","Après à : auquel, à laquelle, auxquels, auxquelles.","Après de avec certaines locutions : près duquel, à côté de laquelle."],"regles":[{"titre":"Formes de base","explication":"Lequel (m.s.), laquelle (f.s.), lesquels (m.p.), lesquelles (f.p.) ; la forme s'accorde avec l'antécédent, non avec le sujet de la relative.","exemple":"La chaise sur laquelle je suis assis ; les moyens avec lesquels il travaille."},{"titre":"Contractions avec à","explication":"À + lequel → auquel ; à + lesquels → auxquels ; à laquelle et auxquelles restent séparés.","exemple":"Le sujet auquel je pense ; les questions auxquelles je réponds."},{"titre":"Contractions avec de","explication":"De + lequel → duquel ; de + lesquels → desquels ; « de laquelle » et « desquelles » restent séparés.","exemple":"Le parc près duquel nous habitons."},{"titre":"Dont ou duquel","explication":"« Dont » convient souvent pour de lié directement au verbe ; après une locution prépositionnelle finissant par de, on choisit fréquemment duquel/de laquelle…","exemple":"La décision dont je parle ; le bâtiment à côté duquel je vis."}],"nuances":["Après une préposition, « qui » est possible pour des personnes : « l'ami avec qui je travaille ».","« Auquel » peut être humain ou non : « le candidat auquel je pense » et « le dossier auquel je travaille » selon la construction."],"pieges":["❌ « Les questions auxquels je réponds » → ✅ « … auxquelles » (f.pl.).","❌ « Le projet dont je participe » → ✅ « … auquel je participe ».","❌ « La table sur lequel » → ✅ « … sur laquelle »."],"retenir":["Préposition + relatif ; antécédent → genre/nombre.","À + lequel = auquel ; de + lequel = duquel."],"methode":["1. Trouve l'antécédent et note f/m, sing./plur.","2. Retrouve la préposition imposée par le verbe.","3. Applique l'accord et la contraction éventuelle."]},"Accord du participe passé":{"objectif":"Le participe passé sert aux temps composés et peut fonctionner comme adjectif. Son accord dépend de l'auxiliaire, de la place du COD et de la construction pronominale : c'est un piège majeur du TCF B2–C2.","quand":["Pour raconter une action au passé : elles sont parties, j'ai choisi.","Quand un complément direct précède un verbe avec avoir : les lettres que j'ai écrites.","Avec des verbes pronominaux : elles se sont parlé / lavées."],"regles":[{"titre":"Sans auxiliaire","explication":"Employé comme adjectif, le participe passé s'accorde avec le nom qualifié.","exemple":"Des décisions prises rapidement ; une porte ouverte."},{"titre":"Avec être","explication":"Le participe passé s'accorde généralement avec le sujet (hors analyse spécifique des pronominaux).","exemple":"Ils sont arrivés ; elle est restée ; elles sont parties."},{"titre":"Avec avoir, COD après ou absent","explication":"Pas d'accord avec le sujet ; si le COD est placé après le participe, le participe reste invariable.","exemple":"Elles ont écrit des lettres ; les candidats ont réussi."},{"titre":"Avec avoir, COD avant","explication":"Accord avec le COD placé avant le participe : pronom le/la/les ou relatif que, selon genre et nombre.","exemple":"Les lettres qu'elle a écrites ; elle les a envoyées."},{"titre":"Pronominaux : COD ou COI","explication":"Si « se » est COD, accord ; si « se » est COI et qu'il n'y a pas de COD avant, pas d'accord avec « se ».","exemple":"Elles se sont lavées ; elles se sont parlé ; elles se sont lavé les mains."},{"titre":"Participe + infinitif","explication":"« Fait » suivi immédiatement d'un infinitif est invariable ; avec « laissé », l'invariabilité devant infinitif est admise par les rectifications. Autres participes : analyse du sujet de l'infinitif.","exemple":"Les robes qu'elle a fait retoucher ; les chanteuses que j'ai entendues chanter."}],"nuances":["« En » COD ne provoque généralement pas l'accord : « Des pommes, j'en ai mangé » ; cas plus complexes discutés par les grammaires.","« Laissé + infinitif » : la graphie invariable (« elle s'est laissé convaincre ») est recommandée par les rectifications orthographiques ; l'usage traditionnel comporte des nuances.","Avec « les trois heures que j'ai dormi », le complément est circonstanciel de durée et non COD : pas d'accord."],"pieges":["❌ « Elles ont écrites des lettres » → ✅ « Elles ont écrit des lettres » (COD après).","❌ « Les lettres que j'ai écrit » → ✅ « Les lettres que j'ai écrites » (COD avant).","❌ « Elles se sont parlées » → ✅ « Elles se sont parlé » (parler à = COI).","❌ « Les réparations que j'ai faites faire » → ✅ « … fait faire » (fait + infinitif)."],"retenir":["Être → sujet ; avoir → COD avant ; pronominal → analyser « se ».","Fait + infinitif reste invariable.","Ne confonds pas COD (qui/quoi ?) et COI (à qui/à quoi ?)."],"methode":["1. Trouve l'auxiliaire ou vérifie l'absence d'auxiliaire.","2. Avec avoir, cherche un COD ET sa position ; s'il est avant, accorde.","3. Avec pronominal, demande « a fait quoi ? à qui ? » et cherche un COD.","4. Vérifie les cas particuliers : fait + infinitif, en, durée."]},"Homophones & orthographe":{"objectif":"Les homophones se prononcent pareil mais s'écrivent différemment. On les reconnaît par la classe grammaticale et des tests de remplacement.","quand":["Pour choisir entre verbe et préposition (a/à, est/et).","Pour distinguer possessif et forme verbale (son/sont).","Pour éviter les pièges de concession (quoique/quoi que, quelque/quel que)."],"regles":[{"titre":"A / à, et / est","explication":"« a » = avait ; « est » = était ; « à » est préposition ; « et » relie deux mots ou groupes.","exemple":"Elle a raison (avait) ; elle va à Rabat ; il est prêt (était) et motivé."},{"titre":"Son / sont, on / ont","explication":"Son = possessif ; sont = étaient. On = pronom ; ont = avaient.","exemple":"Son équipe est prête ; ils sont partis ; on travaille ; ils ont fini."},{"titre":"Ce / se, ces / ses","explication":"Ce/ces = démonstratifs ; se = pronom réfléchi ; ses = possessif pluriel.","exemple":"Ce candidat se présente ; ces dossiers sont ses dossiers."},{"titre":"Ou / où, la / là, leur / leurs","explication":"Ou = choix (ou bien) ; où = lieu/temps ; là = adverbe ; leur pronom COI invariable, leurs déterminant pluriel.","exemple":"Thé ou café ? Où vas-tu ? Je leur donne leurs clés."},{"titre":"Quoique / quoi que","explication":"Quoique = bien que (+ subjonctif). Quoi que = quelle que soit la chose que.","exemple":"Quoiqu'il soit tard, je sors ; quoi que tu fasses, j'aiderai."},{"titre":"Quelque / quel que","explication":"Quelque(s) déterminant = un certain nombre ; quelque adverbe devant adjectif + que = si…que ; quel que + être au subjonctif s'accorde (quelle que soit…).","exemple":"Quelques jours ; quelque difficiles que soient les tâches ; quelles que soient les raisons."}],"nuances":["« Peu » = faible quantité ; « peut » = verbe pouvoir ; « peux » = je/tu peux.","« Censé » = supposé ; « sensé » = raisonnable.","« Plutôt » = de préférence ; « plus tôt » = avant."],"pieges":["❌ « Il à raison » → ✅ « Il a raison » (avait).","❌ « Quoiqu'il arrive, préviens-moi » peut s'écrire « Quoi qu'il arrive » : quelle que soit la chose qui arrive.","❌ « Quelque soient les risques » → ✅ « Quels que soient les risques ».","❌ « Je leurs parle » → ✅ « Je leur parle »."],"retenir":["Ne choisis jamais uniquement à l'oreille : remplace le mot.","Avait → a ; était → est ; ou bien → ou ; si…que → quelque…que ; quel que + être."],"methode":["1. Identifie la catégorie du mot : verbe, pronom, déterminant, adverbe.","2. Tente une substitution fiable (avait/était/ou bien).","3. Pour quel que / quelque, vérifie toute la construction et les accords."]},"Homophones & lexique":{"objectif":"Certains mots très proches provoquent des contresens ou des fautes d'orthographe à niveau B2–C2. Les distinguer aide aussi à comprendre l'intention d'un texte.","quand":["Quand deux mots ne diffèrent que d'une lettre ou d'un accent.","Quand l'homophone change de catégorie grammaticale.","Quand une expression impose une orthographe précise."],"regles":[{"titre":"Censé / sensé","explication":"Censé = supposé/devoir ; sensé = raisonnable, plein de bon sens.","exemple":"Il est censé arriver à midi ; c'est une décision sensée."},{"titre":"Davantage / d'avantage(s)","explication":"Davantage = plus ; d'avantage = de + bénéfice, intérêt ; le sens décide.","exemple":"Je travaille davantage ; je ne vois pas d'avantage à partir."},{"titre":"Quoique / quoi que","explication":"Quoique = bien que ; quoi que = n'importe quelle chose que, souvent suivi du subjonctif.","exemple":"Quoique difficile, c'est possible ; quoi que tu dises, je persiste."},{"titre":"Prémices / prémisse","explication":"Les prémices = premiers signes ; une prémisse = proposition de départ dans un raisonnement.","exemple":"Les prémices d'une crise ; la prémisse d'un argument."},{"titre":"Plutôt / plus tôt","explication":"Plutôt = préférence ou degré ; plus tôt = à un moment antérieur.","exemple":"Je préfère le train plutôt que la voiture ; viens plus tôt."}],"nuances":["Les paronymes ont des sons proches sans être forcément identiques : allusion/illusion, éminent/imminent.","Le registre peut changer la solution : un mot est grammaticalement possible mais sémantiquement imprécis."],"pieges":["❌ « Il est sensé venir » → ✅ « Il est censé venir ».","❌ « Une crise est éminente » → ✅ « imminente » (sur le point de survenir).","❌ « Les prémisses de l'hiver » au sens de premiers signes → ✅ « les prémices de l'hiver »."],"retenir":["Remplace par une définition courte : censé = supposé ; sensé = raisonnable.","Observe le contexte entier, pas seulement le mot isolé."],"methode":["1. Reformule la phrase en langage simple.","2. Teste la définition des mots candidats.","3. Élimine les réponses dont le sens ne convient pas au contexte."]},"Discours rapporté":{"objectif":"Le discours indirect rapporte les paroles ou les pensées d'autrui sans citation directe. Les temps, les pronoms et les repères temporels peuvent changer.","quand":["Pour rapporter une déclaration : il dit qu'il part.","Pour raconter des paroles anciennes : il a dit qu'il partait.","Pour reformuler une question : je me demande où il va."],"regles":[{"titre":"Concordance après un verbe au passé","explication":"Le présent devient souvent imparfait ; passé composé devient plus-que-parfait ; futur devient conditionnel dans le discours indirect au passé.","exemple":"« Je suis prêt » → il a dit qu'il était prêt ; « je viendrai » → il a dit qu'il viendrait."},{"titre":"Questions indirectes","explication":"Pas d'inversion du sujet ni de point d'interrogation dans une subordonnée interrogative indirecte.","exemple":"« Où vas-tu ? » → Il demande où tu vas."},{"titre":"Question oui/non","explication":"« Est-ce que… ? » devient « si… » après demander/se demander, sans conserver est-ce que.","exemple":"« Est-il là ? » → Je me demande s'il est là."},{"titre":"Ordre et repères","explication":"Les pronoms, possessifs et indicateurs de temps se réajustent au point de vue du rapporteur.","exemple":"« Je pars demain » → il a dit qu'il partait le lendemain."}],"nuances":["Si un fait reste vrai au moment où l'on rapporte, le maintien du présent peut être possible selon le contexte.","Le conditionnel dans « il a dit qu'il viendrait » n'implique pas forcément une hypothèse."],"pieges":["❌ « Je me demande où va-t-il » → ✅ « … où il va ».","❌ « Il m'a demandé est-ce que je venais » → ✅ « … si je venais ».","❌ Oublier de changer je/tu/nous dans une citation rapportée."],"retenir":["Après un verbe au passé : présent → imparfait ; futur → conditionnel (souvent).","Question indirecte : pas d'inversion."],"methode":["1. Identifie qui parle, à qui, et quand.","2. Transforme pronoms et repères temporels.","3. Vérifie concordance des temps et structure des questions."]},"Connecteurs & registre":{"objectif":"Les connecteurs indiquent la relation logique entre deux idées : addition, cause, conséquence, opposition, concession, but ou reformulation. Le registre impose parfois un choix plus ou moins soutenu.","quand":["Pour justifier une idée : parce que, puisque, car.","Pour exprimer une conséquence : donc, par conséquent, de sorte que.","Pour nuancer : pourtant, toutefois, néanmoins."],"regles":[{"titre":"Cause","explication":"Parce que répond à pourquoi ; puisque présente une cause supposée connue ; car donne une justification.","exemple":"Je reste parce qu'il pleut ; puisque tu es prêt, partons."},{"titre":"Conséquence","explication":"Donc, ainsi, par conséquent + proposition ; si bien que / de sorte que + indicatif pour un résultat constaté.","exemple":"Il a révisé ; par conséquent, il a progressé."},{"titre":"Opposition / concession","explication":"Mais, cependant, pourtant, toutefois, néanmoins nuancent ce qui précède ; bien que + subjonctif.","exemple":"Il est novice ; néanmoins, il réussit."},{"titre":"But","explication":"Pour que / afin que + subjonctif ; pour / afin de + infinitif quand le sujet est le même.","exemple":"Elle explique pour que chacun comprenne."}],"nuances":["« En effet » confirme/explique une affirmation précédente, alors que « en fait » introduit souvent une rectification.","« D'ailleurs » ajoute un argument ; « pourtant » exprime un contraste inattendu.","« Malgré » se construit avec un nom ou un pronom, pas directement avec « que » dans l'usage soigné."],"pieges":["❌ « Malgré qu'il pleuve » → ✅ « Bien qu'il pleuve » (usage soigné).","❌ « Il est malade, donc il travaille » si l'on veut marquer une surprise → ✅ « pourtant il travaille ».","❌ Confondre « en revanche » et « en conséquence »."],"retenir":["Pose la question : cause ? résultat ? opposition ? but ?","Regarde ensuite la construction : indicatif, subjonctif, infinitif ou nom."],"methode":["1. Lis le sens de deux propositions sans le connecteur.","2. Nomme le lien logique recherché.","3. Vérifie le mode et le registre du mot choisi."]},"Concession & opposition":{"objectif":"L’opposition rapproche deux faits contrastés ; la concession admet un fait sans qu’il empêche ce que dit la proposition principale.","quand":["Pour opposer deux descriptions : l'un est rapide, l'autre lent.","Pour exprimer un résultat surprenant malgré un obstacle.","Pour nuancer un raisonnement B2–C2 sans nier les faits."],"regles":[{"titre":"Alors que / tandis que","explication":"Marquent opposition ou simultanéité selon le contexte ; en valeur oppositive, ils se construisent à l'indicatif.","exemple":"Elle aime la ville, tandis que son frère préfère la campagne."},{"titre":"Bien que / quoique","explication":"Introduisent une concession : le fait admis n'empêche pas le résultat ; suivis du subjonctif.","exemple":"Bien qu'elle soit fatiguée, elle continue."},{"titre":"Malgré / en dépit de","explication":"Ces locutions sont suivies d'un nom, d'un pronom ou d'un groupe nominal, non d'une proposition en « que » dans l'usage soigné.","exemple":"Malgré la pluie, nous sortons ; en dépit des obstacles."},{"titre":"Même si / quand bien même","explication":"Même si est généralement suivi de l'indicatif ; quand bien même introduit une hypothèse concessive et se construit ordinairement avec le conditionnel.","exemple":"Même s'il pleut, je pars ; quand bien même il pleuvrait, je partirais."}],"nuances":["« Cependant » peut relier deux phrases sans subordination ; « bien que » exige une subordonnée.","« Quoiqu'il » = bien qu'il ; « quoi qu'il » = quelle que soit la chose qu'il…"],"pieges":["❌ « Bien qu'il est tard » → ✅ « Bien qu'il soit tard ».","❌ « Malgré qu'il soit compétent » → ✅ « Bien qu'il soit compétent » en français soigné.","❌ « Même s'il serait tard » → ✅ « Même s'il était tard » dans l'hypothèse correspondante."],"retenir":["Bien que → subjonctif ; même si → indicatif ; malgré → nom.","L'opposition simple ne suppose pas toujours une concession."],"methode":["1. Cherche si un obstacle est reconnu mais n'empêche pas le résultat.","2. Choisis la construction adaptée : nom, subordonnée, proposition indépendante.","3. Vérifie le mode verbal imposé."]},"Concession complexe":{"objectif":"Au niveau C1–C2, la concession peut être hypothétique, généralisante ou fortement nuancée. Les formes « quelque…que », « quel que » et les inversions sont des pièges classiques.","quand":["Pour dire « peu importe le degré » : quelque difficile que…","Pour dire « peu importe l'identité ou la nature » : quels que soient…","Pour exprimer une hypothèse reconnue mais inefficace : quand bien même…"],"regles":[{"titre":"Quel que + être","explication":"« Quel que » (en deux mots) s'accorde avec le sujet du verbe être au subjonctif : quel/quelle/quels/quelles que soit/soient.","exemple":"Quelles que soient les difficultés ; quel que soit le résultat."},{"titre":"Quelque + adjectif + que","explication":"« Quelque » adverbe = « si », reste invariable avant l'adjectif ; subjonctif fréquent.","exemple":"Quelque difficiles que soient les épreuves, il persévérera."},{"titre":"Quelque(s) + nom + que","explication":"Déterminant variable devant un nom, selon le sens et le nombre.","exemple":"Quelques objections qu'il formule, il faudra répondre."},{"titre":"Quand bien même","explication":"Hypothèse concessive soutenue, couramment avec le conditionnel ; la principale reste vraie malgré l'hypothèse.","exemple":"Quand bien même il refuserait, nous poursuivrions le projet."},{"titre":"Pour peu que","explication":"Exprime une condition minimale, normalement suivie du subjonctif.","exemple":"Pour peu qu'il fasse beau, nous sortirons."}],"nuances":["« Quoi que » (deux mots) = quelle que soit la chose que, souvent suivi du subjonctif.","« Quoique » (un mot) = bien que ; autre sens et autre structure.","« Aussi…que » et « si…que » peuvent exprimer une concession dans un style soutenu : « Si compétent soit-il… »."],"pieges":["❌ « Quelque soient les circonstances » → ✅ « Quelles que soient les circonstances ».","❌ « Quelques difficiles que soient les tâches » → ✅ « Quelque difficiles que soient… » (adverbe).","❌ « Quand bien même il refuse » → ✅ « Quand bien même il refuserait » dans la tournure concessive habituelle."],"retenir":["Quel que + être → accord ; quelque + adjectif + que → invariable.","Quoique = bien que ; quoi que = quelle que soit la chose que."],"methode":["1. Regarde le mot immédiatement après « quel/quelque » : nom, adjectif ou être ?","2. Applique accord ou invariabilité.","3. Contrôle subjonctif ou conditionnel selon la locution."]},"Articulation argumentative":{"objectif":"L'argumentation exige des liens explicites entre thèse, justification, objection, concession et conclusion. Un connecteur correct grammaticalement peut pourtant exprimer une relation inadaptée.","quand":["Pour développer une démonstration : premièrement, de plus, en outre.","Pour admettre une objection avant de la dépasser : certes…mais ; néanmoins.","Pour conclure : en somme, dès lors, par conséquent."],"regles":[{"titre":"Annonce d'une thèse","explication":"Un énoncé initial pose l'idée à défendre ; les arguments la soutiennent par des faits, des exemples ou un raisonnement.","exemple":"Cette mesure est souhaitable ; en effet, elle réduit le gaspillage."},{"titre":"Addition et renforcement","explication":"De plus, en outre et par ailleurs ajoutent un élément, mais « par ailleurs » peut ouvrir un autre angle plutôt que prouver la même chose.","exemple":"L'offre est peu coûteuse ; en outre, elle est rapide."},{"titre":"Concession argumentative","explication":"Certes introduit souvent un point admis ; « toutefois / néanmoins » annonce une réserve ou une idée plus forte.","exemple":"Certes, le projet coûte cher ; néanmoins, ses bénéfices sont durables."},{"titre":"Déduction","explication":"Dès lors / par conséquent / il s'ensuit que conduisent à une conclusion découlant des prémisses.","exemple":"Les données sont insuffisantes ; dès lors, on ne peut conclure."},{"titre":"Illustration / reformulation","explication":"Par exemple illustre ; autrement dit reformule ; notamment introduit un cas particulier.","exemple":"Cette région manque d'eau, notamment en été."}],"nuances":["« En revanche » oppose deux éléments ; « en conséquence » déduit un effet.","« En effet » peut expliquer ou confirmer ; « en fait » rectifie souvent une première impression.","Une bonne conclusion ne doit pas ajouter une idée qui ne découle pas des arguments."],"pieges":["❌ Utiliser « donc » pour une objection.","❌ « Toutefois » quand la phrase suivante justifie simplement la précédente : préférer « en effet ».","❌ Traiter « notamment » comme « exclusivement »."],"retenir":["Identifie la fonction de chaque phrase, pas seulement le dictionnaire du connecteur.","Certes → concession ; dès lors → déduction ; autrement dit → reformulation."],"methode":["1. Résume chaque proposition en trois mots.","2. Étiquette le lien : exemple, cause, conséquence, objection, reformulation.","3. Sélectionne le connecteur dont la portée logique est exacte."]},"Constructions verbales":{"objectif":"Les verbes français imposent parfois des prépositions, des compléments ou des infinitifs particuliers. Une phrase peut sembler naturelle mais être non conforme au français soigné.","quand":["Pour compléter correctement un verbe par une personne ou une chose.","Pour choisir entre de, à ou zéro préposition.","Pour éviter les confusions entre constructions proches."],"regles":[{"titre":"Verbe + à / de","explication":"Participer à, s'attendre à, se souvenir de, se méfier de ; ces constructions commandent aussi les pronoms relatifs.","exemple":"Il aspire à réussir ; elle se souvient de son voyage."},{"titre":"Verbes directs","explication":"Aider, attendre, pallier, viser, solliciter sont normalement directs dans leurs emplois courants.","exemple":"Elle attend ses résultats ; nous pallions le manque de temps."},{"titre":"Verbe + infinitif","explication":"Espérer + infinitif (même sujet) ; hésiter à, décider de, réussir à, éviter de selon le verbe.","exemple":"Il hésite à partir ; elle décide de postuler."},{"titre":"Faire / laisser + infinitif","explication":"Le sujet provoque ou autorise une action ; l'ordre des pronoms et l'accord du participe peuvent devenir délicats.","exemple":"Il fait réparer sa voiture ; elle laisse partir les invités."},{"titre":"Verbes à sens variable","explication":"Manquer à quelqu'un ≠ manquer quelque chose ; se rappeler quelque chose (direct) ≠ se souvenir de quelque chose.","exemple":"Tu me manques ; j'ai manqué le train ; je me rappelle ce jour."}],"nuances":["« Se rappeler » se construit traditionnellement sans « de » dans l'usage soigné, contrairement à « se souvenir de ».","« Demander à quelqu'un de faire quelque chose », mais « demander quelque chose à quelqu'un ».","Des constructions existent avec plusieurs sens : « penser à », « penser de »."],"pieges":["❌ « Je me rappelle de ce jour » → ✅ « Je me rappelle ce jour » dans l'usage soigné.","❌ « Nous pallions à ce problème » → ✅ « Nous pallions ce problème ».","❌ « Je l'ai téléphoné » → ✅ « Je lui ai téléphoné »."],"retenir":["Apprends chaque verbe avec un complément-type, pas isolément.","La préposition du verbe oriente aussi dont/auquel et le/la/lui."],"methode":["1. Retrouve l'infinitif et sa construction usuelle.","2. Demande si le complément est direct, à ou de.","3. Vérifie si l'infinitif qui suit réclame à/de ou rien."]},"Inversion & style soutenu":{"objectif":"Le français formel emploie certaines inversions du sujet et tournures emphatiques pour souligner une information, une restriction ou une hypothèse.","quand":["Dans une interrogation soutenue : qu'en pensez-vous ?","Après certains adverbes en début de phrase : à peine, encore, peut-être.","Pour exprimer une condition sans si : eût-il su…, fût-ce…"],"regles":[{"titre":"Inversion interrogative","explication":"Sujet pronominal placé après le verbe, avec trait d'union ; -t- euphonique si nécessaire.","exemple":"Pourquoi a-t-elle refusé ?"},{"titre":"À peine…que","explication":"En style soutenu, à peine en tête peut entraîner une inversion ; « que » introduit l'événement suivant.","exemple":"À peine était-il arrivé qu'on l'appela."},{"titre":"Peut-être / sans doute","explication":"En tête de phrase, ces adverbes peuvent entraîner une inversion en style soutenu, ou être suivis de « que ».","exemple":"Peut-être viendra-t-il ; peut-être qu'il viendra."},{"titre":"Encore faut-il que","explication":"Exprime une condition indispensable ou une réserve ; subjonctif après que.","exemple":"Encore faut-il qu'il soit disponible."},{"titre":"Fût-ce / ne serait-ce que","explication":"Tournures de concession, d'hypothèse ou de restriction dans un registre soutenu.","exemple":"Il faut agir, ne serait-ce que par prudence."}],"nuances":["L'inversion n'est pas automatique après n'importe quel adverbe.","L'inversion complexe peut répéter le sujet nominal par un pronom : « Le directeur viendra-t-il ? ».","« À peine…que » peut aussi se construire sans inversion selon la place et le registre."],"pieges":["❌ « Peut-être il viendra » à l'écrit soigné en tête de phrase → ✅ « Peut-être viendra-t-il » ou « Peut-être qu'il viendra ».","❌ « Encore faut-il qu'il est prêt » → ✅ « … qu'il soit prêt ».","❌ Oublier le trait d'union à l'inversion."],"retenir":["À peine…que ; encore faut-il que + subjonctif ; peut-être + inversion ou que.","Vérifie toujours sujet et registre."],"methode":["1. Repère si la phrase est très formelle ou littéraire.","2. Cherche un déclencheur initial d'inversion.","3. Contrôle ponctuation, trait d'union et accord du verbe."]},"Syntaxe littéraire":{"objectif":"Les textes C2 peuvent employer des temps, modes et inversions rares. Les reconnaître suffit souvent à comprendre la phrase ; il n'est pas nécessaire de les utiliser au quotidien.","quand":["Dans la littérature, la critique et les dissertations savantes.","Pour comprendre une condition passée exprimée sans « si ».","Pour interpréter une concession avec subjonctif imparfait ou plus-que-parfait."],"regles":[{"titre":"Subjonctif imparfait","explication":"Forme littéraire correspondant parfois au subjonctif présent dans une subordonnée dépendant d'un verbe au passé.","exemple":"Il fallait qu'il vînt (langue littéraire) ; aujourd'hui : qu'il vienne."},{"titre":"Plus-que-parfait du subjonctif","explication":"Auxiliaire au subjonctif imparfait + participe passé ; marque une antériorité en style littéraire.","exemple":"Il regrettait qu'elle fût partie."},{"titre":"Conditionnel passé, deuxième forme","explication":"Formes du plus-que-parfait du subjonctif utilisées dans certaines constructions conditionnelles littéraires.","exemple":"Eût-il su la vérité, il aurait refusé."},{"titre":"Ne explétif littéraire","explication":"« Ne » peut ne pas nier après certains comparatifs ou locutions ; seul le contexte détermine la valeur.","exemple":"Il agit autrement que je ne l'avais prévu."},{"titre":"Passé simple","explication":"Temps narratif de l'écrit littéraire pour les événements passés ponctuels.","exemple":"Il entra, regarda la salle et s'assit."}],"nuances":["Le passé simple ne se traduit pas par un futur ou un conditionnel : c'est un temps du passé.","« Qu'il eût su » n'est pas la même chose que « il avait su » quant au mode et à la construction.","Le registre de ces tournures est très marqué ; ne les utilise pas sans raison."],"pieges":["❌ Lire « qu'il vînt » comme un présent ordinaire ; c'est un subjonctif imparfait.","❌ Croire que « ne » est toujours une négation.","❌ Confondre « eût » (subjonctif imparfait d'avoir) et « eut » (passé simple)."],"retenir":["Au C2, reconnais d'abord la fonction de la tournure : récit, hypothèse, concession.","Repère les accents : eut / eût ; fut / fût."],"methode":["1. Reformule la phrase en français actuel.","2. Reconstitue condition et conséquence ou proposition principale et subordonnée.","3. Élimine les choix dont le temps ou le mode détruit la chronologie."]},"Lexique avancé":{"objectif":"Le lexique avancé permet d'exprimer une idée avec précision et de comprendre des textes abstraits. Le TCF teste le sens en contexte, les collocations et le registre.","quand":["Pour lire des analyses, éditoriaux et rapports.","Pour distinguer deux mots proches mais non synonymes.","Pour comprendre une nuance de cause, de doute ou d'intensité."],"regles":[{"titre":"Sens contextuel","explication":"Le même mot peut prendre plusieurs sens ; le contexte prime sur la traduction isolée.","exemple":"Une mesure « drastique » est radicale ; « plausible » veut dire crédible."},{"titre":"Paronymes","explication":"Éminent = remarquable ; imminent = sur le point d'arriver. Inhérent = lié à la nature de ; imminent = proche dans le temps.","exemple":"Un expert éminent ; un danger imminent ; des risques inhérents au projet."},{"titre":"Collocations","explication":"Certains noms s'associent naturellement à certains verbes ou adjectifs ; remplacer un mot peut rendre la phrase maladroite.","exemple":"Soulever une objection ; formuler une hypothèse ; émettre une réserve."},{"titre":"Registre","explication":"« Néanmoins » ou « toutefois » sont plus formels que « mais » ; « dénué de » est plus soutenu que « sans ».","exemple":"Un argument dénué de pertinence."}],"nuances":["La négation partielle, l'ironie et les modalisateurs (« prétendument », « vraisemblablement ») modifient l'interprétation.","« Périlleux » = dangereux, pas « qui dure longtemps » ; « pérenne » = durable."],"pieges":["❌ « Un danger éminent » → ✅ « imminent ».","❌ « Un projet périlleux » au sens de durable → ✅ « pérenne ».","❌ Déduire une définition uniquement d'un mot ressemblant à l'anglais."],"retenir":["Toujours tester le sens du mot dans la phrase entière.","Vérifier le registre et les expressions qui vont ensemble."],"methode":["1. Reformule le texte avec des mots simples.","2. Élimine les réponses qui changent l'intensité, le temps ou le registre.","3. Cherche les associations lexicales usuelles."]},"Précision lexicale":{"objectif":"La précision lexicale consiste à choisir le terme exact parmi des synonymes partiels. En C1–C2, une réponse peut sembler acceptable mais produire une nuance inappropriée.","quand":["Quand on exprime l'intensité, la certitude ou le jugement.","Quand la phrase appartient à un registre académique ou administratif.","Quand il faut distinguer cause, effet et condition."],"regles":[{"titre":"Nuance entre synonymes","explication":"« Probable » = fortes chances ; « possible » = concevable ; « certain » = sûr.","exemple":"Il est possible qu'il vienne ; il est probable qu'il viendra."},{"titre":"Préfixes et sens","explication":"Pré-, post-, sous-, sur-, anti-, co- orientent le sens mais ne suffisent pas toujours pour deviner un mot.","exemple":"Sous-estimer un coût ≠ surestimer un coût."},{"titre":"Verbes de raisonnement","explication":"Déduire une conclusion, inférer une idée, postuler une hypothèse : les constructions varient.","exemple":"On peut inférer une intention de ses propos."},{"titre":"Intensité et degré","explication":"« Minime », « négligeable », « marginal » expriment des nuances et ne sont pas interchangeables dans toutes les phrases.","exemple":"Un coût marginal ; une erreur négligeable."}],"nuances":["« Dépourvu de » = sans ; « émaillé de » = ponctué de ; « étayé par » = soutenu par des preuves.","Un mot grammaticalement correct peut être écarté parce que sa portée est trop forte ou trop faible."],"pieges":["❌ « Une preuve plausible » quand on veut parler de solidité factuelle → préférer « convaincante » si le contexte le demande.","❌ « Déduire un résultat » et « induire un comportement » sont deux mécanismes différents.","❌ Confondre « exacerber » (aggraver/intensifier) et « exaspérer » (irriter)."],"retenir":["Lis le nom autour du mot : la compatibilité sémantique est décisive.","Teste l'intensité, la certitude et le registre."],"methode":["1. Identifie exactement l'idée à transmettre.","2. Compare l'intensité et la connotation des choix.","3. Vérifie la collocation et le registre final."]},"Pragmatique & cohérence":{"objectif":"La cohérence pragmatique concerne ce qu'une phrase veut faire : nuancer, concéder, demander, sous-entendre ou réfuter. Le bon choix respecte la logique et le ton du passage.","quand":["Pour comprendre un sous-entendu ou une réserve diplomatique.","Pour interpréter une formule indirecte ou une double négation.","Pour choisir un connecteur compatible avec l'intention."],"regles":[{"titre":"Présupposé","explication":"Certaines expressions supposent déjà un fait : « Il a cessé de fumer » présuppose qu'il fumait auparavant.","exemple":"Elle a recommencé à étudier (elle étudiait déjà avant)."},{"titre":"Atténuation","explication":"« Il semblerait que », « à première vue », « sous réserve de » diminuent le degré d'engagement.","exemple":"Il semblerait que la mesure ait un effet."},{"titre":"Restriction","explication":"« Du moins », « sauf à », « ne…que » limitent la portée d'un énoncé.","exemple":"Le projet est viable, du moins à court terme."},{"titre":"Concession et réfutation","explication":"Reconnaître un fait ne signifie pas accepter la conclusion tirée : « certes…mais » ; « nonobstant » = malgré.","exemple":"Nonobstant les objections, la décision fut adoptée."},{"titre":"Cohérence interphrastique","explication":"Un lien logique doit être compatible avec toutes les phrases et leur temporalité, pas avec un mot isolé.","exemple":"Les données manquent ; par conséquent, la conclusion est prématurée."}],"nuances":["« Je ne dis pas que c'est faux » n'affirme pas nécessairement que c'est vrai.","« Ce n'est pas impossible » exprime une possibilité, pas une certitude.","Le sarcasme et l'ironie peuvent inverser l'effet pragmatique apparent."],"pieges":["❌ Lire « nonobstant » comme « grâce à » → ✅ « malgré ».","❌ Lire « du moins » comme « au minimum » dans tous les contextes : il peut rectifier/restrindre.","❌ Traiter un sous-entendu comme un fait explicitement affirmé."],"retenir":["Sépare ce qui est affirmé, présupposé et suggéré.","Fais attention à la portée des négations et des restrictions."],"methode":["1. Reformule l'intention du locuteur.","2. Distingue certitude, possibilité, concession et réserve.","3. Teste si chaque option maintient l'enchaînement logique."]},"Locutions & expressions":{"objectif":"Les locutions sont des groupes de mots dont la construction et le sens sont relativement figés. Les maîtriser permet de comprendre les textes formels et d'éviter des associations incorrectes.","quand":["Pour exprimer but, concession, condition, délai ou précision.","Pour reconnaître un registre soutenu dans des textes C1–C2.","Pour sélectionner le bon mode après une expression."],"regles":[{"titre":"À condition que / pourvu que","explication":"Exigent généralement le subjonctif, car l'action dépend d'une condition souhaitée.","exemple":"Nous sortirons pourvu qu'il ne pleuve pas."},{"titre":"De sorte que","explication":"Indicatif si conséquence réalisée, subjonctif si résultat recherché selon l'intention et le contexte.","exemple":"Il a parlé fort de sorte que tous l'ont entendu ; il parle fort de sorte que tous l'entendent (but)."},{"titre":"Faute de / à défaut de","explication":"Introduisent une absence ou un remplacement, suivis d'un nom, d'un pronom ou d'un infinitif selon la construction.","exemple":"Faute de temps, nous renonçons ; à défaut d'accord, on reportera."},{"titre":"Au demeurant / a fortiori","explication":"Au demeurant = d'ailleurs/à bien considérer ; a fortiori = à plus forte raison.","exemple":"C'est déconseillé aux débutants, a fortiori aux enfants."},{"titre":"D'autant plus que","explication":"Renforce un argument en apportant une raison supplémentaire, suivi généralement de l'indicatif.","exemple":"Je refuse, d'autant plus que le délai est dépassé."}],"nuances":["« Tant que » exprime la durée ou une condition persistante ; « jusqu'à ce que » prend le subjonctif.","« En vertu de » = sur le fondement de ; « en vue de » = dans le but de.","« Ne serait-ce que » exprime une raison minimale suffisante."],"pieges":["❌ « À condition qu'il vient » → ✅ « … qu'il vienne ».","❌ « En vue que » → ✅ « En vue de + nom/infinitif » ou « afin que + subjonctif ».","❌ Traiter « a fortiori » comme une simple opposition."],"retenir":["Une locution s'apprend avec sa construction et son sens exact.","Condition/but : surveiller le subjonctif ; cause : souvent indicatif."],"methode":["1. Repère les mots qui forment la locution entière.","2. Détermine son sens logique.","3. Vérifie quelle forme suit : nom, infinitif, indicatif, subjonctif."]},"Comparaison & quantité":{"objectif":"Les comparatifs et quantificateurs situent un élément par rapport à un autre ou précisent une quantité. Ils obéissent à des structures fixes et à quelques formes irrégulières.","quand":["Pour comparer : plus, moins, aussi / autant.","Pour exprimer une superlativité : le plus, la meilleure.","Pour indiquer quantité ou intensité : beaucoup de, peu de, tellement de."],"regles":[{"titre":"Comparatif avec adjectif","explication":"Plus / moins / aussi + adjectif + que ; l'adjectif s'accorde avec le nom.","exemple":"Elle est aussi efficace que lui ; ces questions sont plus difficiles."},{"titre":"Comparatif avec nom","explication":"Plus / moins / autant de + nom + que ; pas « aussi de ».","exemple":"J'ai autant de livres que toi."},{"titre":"Comparatifs irréguliers","explication":"Bon → meilleur ; bien → mieux ; mauvais → pire / plus mauvais selon l'usage.","exemple":"Cette solution est meilleure ; elle travaille mieux."},{"titre":"Superlatif","explication":"Le/la/les plus ou le/la/les moins + adjectif ; avec un adjectif, la position de l'article dépend de la construction.","exemple":"C'est la meilleure réponse ; les solutions les plus utiles."},{"titre":"Quantité","explication":"Beaucoup de, trop de, peu de, assez de + nom ; l'article peut réapparaître dans un sens défini particulier.","exemple":"J'ai peu de temps ; beaucoup d'idées."}],"nuances":["« Plus bon » est généralement remplacé par « meilleur » dans la comparaison de qualité ; « plus bien » par « mieux ».","« Autant » s'emploie avec le nom ou le verbe ; « aussi » avec adjectif/adverbe dans la comparaison d'égalité."],"pieges":["❌ « Elle est plus meilleure » → ✅ « Elle est meilleure ».","❌ « Aussi de livres » → ✅ « Autant de livres ».","❌ « beaucoup des personnes » (sens général) → ✅ « beaucoup de personnes »."],"retenir":["Aussi + adjectif/adverbe ; autant de + nom.","Bon → meilleur ; bien → mieux."],"methode":["1. Identifie ce qui est comparé : qualité, action ou quantité.","2. Choisis aussi/autant/plus/moins et que si nécessaire.","3. Vérifie les formes irrégulières et les accords."]},"Conditionnel présent":{"objectif":"Le conditionnel présent sert à parler d'hypothèses, de souhaits, de demandes polies ou d'informations rapportées avec prudence. Il peut aussi exprimer le futur dans le passé.","quand":["Pour une demande : pourriez-vous m'aider ?","Pour une hypothèse : je partirais si j'avais le temps.","Pour une supposition ou une information non certaine : il serait absent."],"regles":[{"titre":"Formation","explication":"Radical du futur + terminaisons de l'imparfait : -ais, -ais, -ait, -ions, -iez, -aient.","exemple":"Je ferais, nous pourrions, elle viendrait."},{"titre":"Hypothèse irréelle au présent","explication":"Si + imparfait → conditionnel présent dans la conséquence.","exemple":"Si je parlais couramment français, je postulerais."},{"titre":"Politesse","explication":"Pourriez-vous…, voudriez-vous…, j'aimerais… atténuent une demande.","exemple":"Je voudrais un renseignement."},{"titre":"Futur dans le passé","explication":"Après un verbe au passé, le conditionnel exprime ce qui était futur à ce moment-là.","exemple":"Il a promis qu'il viendrait."},{"titre":"Information prudente","explication":"Le conditionnel peut indiquer une information rapportée non confirmée.","exemple":"Le candidat serait retenu selon plusieurs sources."}],"nuances":["« Je voudrais » n'implique pas nécessairement qu'une condition soit présente : c'est aussi une formule de politesse.","Le futur simple ressemble au conditionnel à la 1re personne ; compare -rai et -rais."],"pieges":["❌ « Si je serais disponible » → ✅ « Si j'étais disponible ».","❌ « Je pourrait » → ✅ « Je pourrais ».","❌ Lire tout conditionnel comme une incertitude : il peut être un futur dans le passé."],"retenir":["Radical futur + terminaisons imparfait.","Si + imparfait → conditionnel présent."],"methode":["1. Cherche la valeur de la phrase (hypothèse, politesse, avenir du passé).","2. Repère la présence et le temps d'une proposition introduite par si.","3. Vérifie radical et terminaison."]},"Relatifs & prépositions":{"objectif":"Les pronoms relatifs et les prépositions fonctionnent ensemble : c'est la construction du verbe qui détermine le choix de « dont », « auquel », « sur lequel », etc.","quand":["Pour combiner deux phrases sans changer la préposition du verbe.","Pour reprendre des compléments de lieu ou de temps.","Pour différencier des constructions proches : parler de / penser à."],"regles":[{"titre":"De + complément","explication":"Si le complément d'un verbe est introduit par de, « dont » est souvent approprié (sauf après certaines locutions complexes).","exemple":"Le problème dont nous parlons."},{"titre":"À + complément","explication":"« Auquel/à laquelle/auxquels/auxquelles » remplacent à + chose ; « à qui » est courant avec une personne.","exemple":"Le dossier auquel je pense ; la personne à qui je parle."},{"titre":"Autres prépositions","explication":"Avec, sur, dans, pour, sans… demandent en général une forme de lequel/laquelle/lesquels/lesquelles pour une chose.","exemple":"La règle sur laquelle je m'appuie."},{"titre":"Préposition composée","explication":"Après près de, à côté de, au milieu de, on utilise souvent duquel/de laquelle… ; « dont » ne remplace pas mécaniquement toutes les constructions.","exemple":"La maison à côté de laquelle je vis."},{"titre":"Accord","explication":"Le relatif composé s'accorde avec le nom repris (antécédent) et non avec le nom le plus proche.","exemple":"Les méthodes auxquelles elle recourt."}],"nuances":["« Y » remplace souvent à + chose, « en » remplace souvent de + chose ; la même logique aide à identifier les relatifs.","« La ville où je vis » mais « le projet auquel je participe » : où ne marche pas pour n'importe quel complément."],"pieges":["❌ « La méthode dont j'ai recours » → ✅ « La méthode à laquelle j'ai recours ».","❌ « Les sujets auquel je pense » → ✅ « … auxquels ».","❌ « Le dossier que je parle » → ✅ « … dont je parle »."],"retenir":["Apprends verbes avec leur préposition.","Prép. « de » → souvent dont ; « à » → auquel ; autres → prép. + lequel."],"methode":["1. Rétablis le verbe avec son complément.","2. Repère la préposition correcte.","3. Choisis le relatif et applique genre/nombre."]},"Subtilités des modes":{"objectif":"Le choix du mode (indicatif, subjonctif, conditionnel) dépend de la façon dont le locuteur présente le fait : réel, souhaité, incertain, hypothétique ou concédé.","quand":["Pour exprimer un fait établi : indicatif.","Pour exprimer un souhait, un doute ou une nécessité : souvent subjonctif.","Pour exprimer une hypothèse ou la prudence : conditionnel."],"regles":[{"titre":"Indicatif de fait","explication":"Le locuteur présente l'événement comme un fait ou une certitude.","exemple":"Je sais qu'elle vient ; il est évident qu'il réussira."},{"titre":"Subjonctif de perspective","explication":"Il est fréquent après des déclencheurs de nécessité, désir, doute, but, concession.","exemple":"Je veux qu'il vienne ; bien qu'il pleuve, je sors."},{"titre":"Conditionnel d'hypothèse","explication":"Hypothèse présente irréelle (si + imparfait), passée irréelle (si + plus-que-parfait → conditionnel passé).","exemple":"Si j'avais le temps, je voyagerais ; si j'avais su, je serais venu."},{"titre":"Avant que / après que","explication":"Avant que + subjonctif ; après que + indicatif dans la norme soignée.","exemple":"Avant qu'il parte ; après qu'il est parti."},{"titre":"Jusqu'à ce que / dès que","explication":"Jusqu'à ce que + subjonctif ; dès que + indicatif, avec futur si événement à venir.","exemple":"J'attends jusqu'à ce qu'il arrive ; dès qu'il arrivera, nous partirons."}],"nuances":["Certaines interrogatives ou négations après croire/penser peuvent favoriser le subjonctif sans imposer une règle absolue.","« Il semble que » et « il me semble que » peuvent se construire différemment selon l'usage et le degré de certitude.","Au C2, subjonctif littéraire et inversion demandent parfois une reformulation en français courant."],"pieges":["❌ « Je sais qu'il soit prêt » → ✅ « Je sais qu'il est prêt ».","❌ « Avant qu'il vient » → ✅ « Avant qu'il vienne ».","❌ « Si j'aurais pu » → ✅ « Si j'avais pu »."],"retenir":["Mode = attitude du locuteur envers le fait.","Repérer le déclencheur ne suffit pas toujours : lire la phrase entière."],"methode":["1. Décide : fait, souhait/doute, hypothèse ou concession ?","2. Lis les locutions qui imposent un mode.","3. Contrôle la concordance temporelle et la forme du verbe."]}};
